ui:{examT:'Na prova (CKA)',lessons:'lições',progress:'Progresso',search:'Buscar lições e conceitos…',noResults:'Nada encontrado.',theme:'Tema',themeLight:'Tema claro',themeDark:'Tema escuro',inDiagram:'Neste passo',course:'Trilha do curso',steps:'passos',lesson:'Lição',of:'de',step:'Passo',key:'Ideia-chave',good:'Bom saber',warn:'Atenção',changed:'O que mudou',copy:'Copiar',copied:'Copiado',copyFail:'Selecione e copie',end:'Fim do curso',nextLesson:'Próxima lição',next:'Próximo',replay:'Repetir',pause:'Pausar',resume:'Continuar',full:'Tela cheia',inLesson:'Nesta lição',back:'Voltar',kStep:'passo',kReplay:'repetir',kPause:'pausar',learn:'Você vai aprender',openMenu:'Abrir lições',lang:'Idioma',leg_req:'requisição',leg_heavy:'requisição pesada',leg_hc:'health check',leg_bad:'requisição com falha'},
